-- 70 Eight Ways: the ranger's skeletal player is a 2D blend space of nine
-- clips (idle, and a walk and a run each way). Its body turns to aim at a
-- target; its velocity, turned into the body's frame, is where it is in the
-- blend space (Animation.set_blend_position) - so its feet step the way it
-- is going relative to where it faces. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/70-eight-ways.scene"
local WALK, RUN = 95.0, 200.0
local TARGETS = { { -430.0, 170.0 }, { 440.0, 205.0 }, { 360.0, -215.0 }, { -400.0, -200.0 } }
local IX, IY, IS = 520.0, -235.0, 34.0
local atan2 = math.atan2 or math.atan
local captions = true
local ranger, arrow, nocked, dot
local x, y, aim, s, t = 0, 0, 0, 0, 0
local target, since_shot = 1, 0
local flight = nil

-- A wandering loop round the clearing, walked at a pace that swells from a
-- standstill to a run.
local function path(u)
    return 310 * math.sin(u * 0.23) + 90 * math.sin(u * 0.61), 165 * math.sin(u * 0.37 + 1) + 55 * math.cos(u * 0.53)
end

local function wrap(a)
    while a > math.pi do a = a - 2 * math.pi end
    while a < -math.pi do a = a + 2 * math.pi end
    return a
end

function init(entity)
    ranger = Entity.find_by_name("Ranger")
    arrow = Entity.find_by_name("Arrow")
    nocked = Entity.find_by_name("Nocked")
    dot = Entity.find_by_name("BlendDot")
    x, y = path(0)
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if dt <= 0 then return end
    t = t + dt
    s = s + dt * math.max(0, 1.15 + 1.05 * math.sin(t * 0.21))
    local nx, ny = path(s)
    local vx, vy = (nx - x) / dt, (ny - y) / dt
    x, y = nx, ny
    -- Aim: turn toward the current target, a new one every few seconds.
    since_shot = since_shot + dt
    local tx, ty = TARGETS[target][1], TARGETS[target][2]
    local want = atan2(ty - y, tx - x)
    local turn = wrap(want - aim)
    local step = 4.0 * dt
    aim = aim + math.max(-step, math.min(step, turn))
    Transform.set_position(ranger, x, y)
    Transform.set_rotation(ranger, aim)
    -- The velocity in the body's frame, scaled so the walk points sit at 1
    -- and the run points at 2.
    local lx = vx * math.cos(aim) + vy * math.sin(aim)
    local ly = -vx * math.sin(aim) + vy * math.cos(aim)
    local speed = math.sqrt(lx * lx + ly * ly)
    local mag = speed <= WALK and speed / WALK or math.min(2, 1 + (speed - WALK) / (RUN - WALK))
    local bx, by = 0, 0
    if speed > 0.001 then bx, by = lx / speed * mag, ly / speed * mag end
    Animation.set_blend_position(ranger, bx, by)
    Transform.set_position(dot, IX + bx * IS, IY + by * IS)
    -- Loose an arrow once the aim is on, then pick the next target.
    if flight == nil and since_shot > 2.4 and math.abs(turn) < 0.04 then
        flight = { t = 0, x0 = x + 30 * math.cos(aim), y0 = y + 30 * math.sin(aim), x1 = tx, y1 = ty, a = aim }
        Sprite.set_color(nocked, 1, 1, 1, 0)
    end
    if flight then
        flight.t = flight.t + dt
        local k = math.min(1, flight.t / 0.3)
        Transform.set_position(arrow, flight.x0 + (flight.x1 - flight.x0) * k, flight.y0 + (flight.y1 - flight.y0) * k)
        Transform.set_rotation(arrow, flight.a)
        if flight.t > 0.5 then Sprite.set_color(nocked, 1, 1, 1, 1) end
        if flight.t > 1.4 then
            Transform.set_position(arrow, 0, -2000)
            flight = nil
            since_shot = 0
            target = target % #TARGETS + 1
        end
    end
end
